import type { ReactElement } from "react";
import {
  type ConversationEvent,
  ConversationEventType,
  type Flow,
  type UnionEventType,
  UtteranceType,
} from "../../types";
import { isConversationEvent, isUtterance } from "../../utils";
import { SkillEventInfo } from "./SkillEventInfo";
import { OrderedBlockEventInfo } from "./OrderedBlockEventInfo";
import { ActionEventInfo } from "./ActionEventInfo";
import { AgentEventInfo } from "./AgentEventInfo";
import { BotMessageInfo } from "./BotMessageInfo";
import { BotTurnEndedEventInfo } from "./BotTurnEndedEventInfo";
import { BargeInEventInfo } from "./BargeInEventInfo";
import { TtsFinishedEventInfo } from "./TtsFinishedEventInfo";
import { FlowEventInfo } from "./FlowEventInfo";
import { LlmCallEventInfo } from "./LlmCallEventInfo";
import { McpToolExecutedEventInfo } from "./McpToolExecutedEventInfo";
import { ToolExecutedEventInfo } from "./ToolExecutedEventInfo";
import { PlainEventInfo } from "./PlainEventInfo";
import { MemoryClearedEventInfo } from "./MemoryClearedEventInfo";
import { MemorySetEventInfo } from "./MemorySetEventInfo";
import { SlotEventInfo } from "./SlotEventInfo";
import { UserMessageInfo } from "./UserMessageInfo";
import { UserInputSuppressedEventInfo } from "./UserInputSuppressedEventInfo";
import { UserSilenceTimeoutEventInfo } from "./UserSilenceTimeoutEventInfo";

function isFlowEvent(event: ConversationEvent): boolean {
  return [
    ConversationEventType.FlowCancelled,
    ConversationEventType.FlowCompleted,
    ConversationEventType.FlowInterrupted,
    ConversationEventType.FlowResumed,
    ConversationEventType.FlowStarted,
  ].includes(event.conversationEventType);
}

function isSlotEvent(event: ConversationEvent): boolean {
  return (
    event.conversationEventType === ConversationEventType.ResetSlots ||
    event.conversationEventType === ConversationEventType.Slot
  );
}

function isSkillEvent(event: ConversationEvent): event is ConversationEvent & { skillId: string } {
  return (
    [
      ConversationEventType.SkillActivated,
      ConversationEventType.SkillCompleted,
      ConversationEventType.SkillCancelled,
      ConversationEventType.SkillInterrupted,
      ConversationEventType.SkillResumed,
    ].includes(event.conversationEventType) &&
    typeof event.skillId === "string" &&
    event.skillId.length > 0
  );
}

function isOrderedBlockEvent(
  event: ConversationEvent,
): event is ConversationEvent & { skillId: string; blockId: string } {
  return (
    [
      ConversationEventType.OrderedBlockEntered,
      ConversationEventType.OrderedBlockCompleted,
      ConversationEventType.OrderedBlockCancelled,
      ConversationEventType.OrderedBlockInterrupted,
      ConversationEventType.OrderedBlockResumed,
    ].includes(event.conversationEventType) &&
    typeof event.skillId === "string" &&
    event.skillId.length > 0 &&
    typeof event.blockId === "string" &&
    event.blockId.length > 0
  );
}

function isActionEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.Action;
}

function isLlmCallEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.LlmCallRecorded;
}

function isAgentEvent(event: ConversationEvent): boolean {
  return [
    ConversationEventType.AgentStarted,
    ConversationEventType.AgentCompleted,
    ConversationEventType.AgentCancelled,
    ConversationEventType.AgentInterrupted,
    ConversationEventType.AgentResumed,
  ].includes(event.conversationEventType);
}

function isBotTurnEndedEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.BotTurnEnded;
}

function isTtsFinishedEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.TtsFinished;
}

function isBargeInEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.UserBargeIn;
}

function isUserInputSuppressedEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.UserInputSuppressed;
}

function isUserSilenceTimeoutEvent(event: ConversationEvent): boolean {
  return event.conversationEventType === ConversationEventType.UserSilenceTimeout;
}

interface EventInfoProps {
  event: UnionEventType;
  onClose: () => void;
  flows: Flow[];
}

function renderUtteranceInfo(event: UnionEventType, onClose: () => void): ReactElement | null {
  if (!isUtterance(event)) {
    return null;
  }
  if (event.type === UtteranceType.Bot) {
    return <BotMessageInfo utterance={event} onClose={onClose} />;
  }
  return <UserMessageInfo utterance={event} onClose={onClose} />;
}

function renderMemoryWriteInfo(event: ConversationEvent, onClose: () => void): ReactElement | null {
  if (event.conversationEventType === ConversationEventType.MemorySet) {
    return <MemorySetEventInfo event={event} onClose={onClose} />;
  }
  if (event.conversationEventType === ConversationEventType.MemoryCleared) {
    return <MemoryClearedEventInfo event={event} onClose={onClose} />;
  }
  return null;
}

function renderToolRunInfo(event: ConversationEvent, onClose: () => void): ReactElement | null {
  if (event.conversationEventType === ConversationEventType.ToolExecuted) {
    return <ToolExecutedEventInfo event={event} onClose={onClose} />;
  }
  if (event.conversationEventType === ConversationEventType.McpToolExecuted) {
    return <McpToolExecutedEventInfo event={event} onClose={onClose} />;
  }
  return null;
}

export const EventInfo = ({ event, onClose, flows }: EventInfoProps) => {
  const utteranceInfo = renderUtteranceInfo(event, onClose);
  if (utteranceInfo) {
    return utteranceInfo;
  }

  if (!isConversationEvent(event)) {
    return null;
  }

  if (isFlowEvent(event)) {
    const flow = flows.find((f) => f.id === event.flowId || f.name === event.flowId);
    return <FlowEventInfo event={event} flow={flow} onClose={onClose} />;
  }

  if (isSkillEvent(event)) {
    return <SkillEventInfo event={event} onClose={onClose} />;
  }

  if (isOrderedBlockEvent(event)) {
    return <OrderedBlockEventInfo event={event} onClose={onClose} />;
  }

  const memoryWriteInfo = renderMemoryWriteInfo(event, onClose);
  if (memoryWriteInfo) {
    return memoryWriteInfo;
  }

  if (isSlotEvent(event)) {
    return <SlotEventInfo event={event} onClose={onClose} />;
  }

  if (isActionEvent(event)) {
    return <ActionEventInfo event={event} onClose={onClose} />;
  }

  const toolRunInfo = renderToolRunInfo(event, onClose);
  if (toolRunInfo) {
    return toolRunInfo;
  }

  if (isLlmCallEvent(event)) {
    return <LlmCallEventInfo event={event} onClose={onClose} />;
  }

  if (isAgentEvent(event)) {
    return <AgentEventInfo event={event} onClose={onClose} />;
  }

  if (isBotTurnEndedEvent(event)) {
    return <BotTurnEndedEventInfo event={event} onClose={onClose} />;
  }

  if (isTtsFinishedEvent(event)) {
    return <TtsFinishedEventInfo event={event} onClose={onClose} />;
  }

  if (isBargeInEvent(event)) {
    return <BargeInEventInfo event={event} onClose={onClose} />;
  }

  if (isUserInputSuppressedEvent(event)) {
    return <UserInputSuppressedEventInfo event={event} onClose={onClose} />;
  }

  if (isUserSilenceTimeoutEvent(event)) {
    return <UserSilenceTimeoutEventInfo event={event} onClose={onClose} />;
  }

  return <PlainEventInfo event={event} onClose={onClose} />;
};
